import { useState } from 'react';
import type { ReactElement } from 'react';
import { panelStyle } from './Component.styles';

export type Item = { id: string; label: string };
export type Props = {
  initialItems: Item[];
  onChange: (ids: string[]) => void;
};

export function Component({ initialItems, onChange }: Props): ReactElement {
  const [items, setItems] = useState<Item[]>((): Item[] => [...initialItems]);

  function move(index: number, direction: -1 | 1): void {
    const target: number = index + direction;
    if (index < 0 || index >= items.length || target < 0 || target >= items.length) {
      return;
    }
    const current: Item | undefined = items[index];
    const neighbor: Item | undefined = items[target];
    if (current === undefined || neighbor === undefined) return;

    const nextItems: Item[] = [...items];
    nextItems[index] = neighbor;
    nextItems[target] = current;
    const ids: string[] = nextItems.map((item: Item): string => item.id);
    setItems(nextItems);
    onChange(ids);
  }

  return (
    <div data-testid="panel" style={panelStyle}>
      {items.length === 0 && <div role="status">No items</div>}
      <ul aria-label="Items">
        {items.map((item: Item, index: number): ReactElement => (
          <li key={item.id}>
            <span>{item.label}</span>
            <button
              type="button"
              disabled={index === 0}
              onClick={(): void => move(index, -1)}
            >
              Up {item.id}
            </button>
            <button
              type="button"
              disabled={index === items.length - 1}
              onClick={(): void => move(index, 1)}
            >
              Down {item.id}
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
}
